<?php
declare(strict_types=1);require_once __DIR__.'/includes/store.php';$pageTitle='Checkout';$cart=cart_contents();if(!$cart['items'])redirect('cart.php');$user=customer_user();$errors=[];$successOrder='';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!csrf_is_valid($_POST['csrf_token']??null)){http_response_code(419);exit('Invalid form token. Refresh and try again.');}$name=trim((string)($_POST['customer_name']??''));$email=trim((string)($_POST['customer_email']??''));$phone=trim((string)($_POST['customer_phone']??''));$county=trim((string)($_POST['county']??''));$town=trim((string)($_POST['town']??''));$address=trim((string)($_POST['delivery_address']??''));$notes=trim((string)($_POST['delivery_notes']??''));$payment='mpesa';$reference=strtoupper(trim((string)($_POST['mpesa_reference']??'')));if($name===''||$phone===''||$county===''||$town===''||$address==='')$errors[]='Complete all required delivery fields.';if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email address.';if($reference!==''&&!preg_match('/^[A-Z0-9]{6,20}$/',$reference))$errors[]='Check the M-Pesa transaction code. Use 6–20 letters or numbers.';
 if(!$errors){try{$pdo->beginTransaction();$fee=(float)setting('default_delivery_fee','0.00');$total=$cart['subtotal']+$fee;$number='BC'.date('ymd').strtoupper(bin2hex(random_bytes(3)));$s=$pdo->prepare("INSERT INTO orders(order_number,user_id,customer_name,customer_email,customer_phone,county,town,delivery_address,delivery_notes,order_channel,status,payment_method,payment_status,subtotal,delivery_fee,total_amount) VALUES(?,?,?,?,?,?,?,?,?,'website','pending','mpesa','pending',?,?,?)");$s->execute([$number,$user['id']??null,$name,$email?:null,$phone,$county,$town,$address,$notes?:null,$cart['subtotal'],$fee,$total]);$orderId=(int)$pdo->lastInsertId();$line=$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,sku,unit_price,quantity,line_total) VALUES(?,?,?,?,?,?,?)');$stock=$pdo->prepare('SELECT id,name,sku,price,stock_quantity,is_active FROM products WHERE id=? FOR UPDATE');foreach($cart['items'] as $item){$stock->execute([(int)$item['id']]);$fresh=$stock->fetch();if(!$fresh||(int)$fresh['is_active']!==1||(int)$fresh['stock_quantity']<(int)$item['quantity'])throw new RuntimeException('Stock changed for '.$item['name'].'. Please review your cart.');$line->execute([$orderId,$fresh['id'],$fresh['name'],$fresh['sku'],(float)$fresh['price'],(int)$item['quantity'],(float)$fresh['price']*(int)$item['quantity']]);}$paymentStmt=$pdo->prepare("INSERT INTO payments(order_id,provider,amount,status,transaction_reference) VALUES(?,'mpesa',?,'pending',?)");$paymentStmt->execute([$orderId,$total,$reference?:null]);$pdo->commit();$_SESSION['cart']=[];$_SESSION['last_order_number']=$number;redirect('order-confirmation.php?order='.urlencode($number));}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$errors[]=$e instanceof RuntimeException?$e->getMessage():'We could not place the order. Please check your details and try again.';}}
}
require __DIR__.'/includes/header.php';?><section class="container py-5"><h1 class="h2 mb-4">Checkout</h1><?php foreach($errors as $err):?><div class="alert alert-danger"><?=e($err)?></div><?php endforeach;?><div class="row g-4"><div class="col-lg-7"><form method="post" class="card border-0 shadow-sm p-4"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><h2 class="h5 mb-3">Delivery details</h2><div class="row g-3"><div class="col-md-6"><label class="form-label">Full name *</label><input class="form-control" name="customer_name" required value="<?=e((string)($user['full_name']??''))?>"></div><div class="col-md-6"><label class="form-label">Phone number *</label><input class="form-control" name="customer_phone" required value="<?=e((string)($user['phone']??''))?>"></div><div class="col-12"><label class="form-label">Email (optional)</label><input class="form-control" type="email" name="customer_email" value="<?=e((string)($user['email']??''))?>"></div><div class="col-md-6"><label class="form-label">County *</label><input class="form-control" name="county" required></div><div class="col-md-6"><label class="form-label">Town *</label><input class="form-control" name="town" required></div><div class="col-12"><label class="form-label">Delivery address / landmark *</label><input class="form-control" name="delivery_address" required></div><div class="col-12"><label class="form-label">Delivery notes</label><textarea class="form-control" name="delivery_notes" rows="2"></textarea></div></div><hr><h2 class="h5">Manual M-Pesa payment</h2><p class="text-secondary small">Use the store's configured Paybill/Till instructions below. After paying, you may enter the transaction code; staff must verify it before payment is approved.</p><div class="alert alert-info"><strong>Payment instructions</strong><br><?=nl2br(e(setting('mpesa_instructions','Contact the store to confirm the current M-Pesa Paybill or Till number before sending payment.')))?> </div><label class="form-label">M-Pesa transaction code (optional)</label><input class="form-control" name="mpesa_reference" maxlength="20" placeholder="e.g. QAB12CDE34"><button class="btn btn-primary btn-lg mt-4">Place order</button><small class="text-secondary mt-2">Placing the order does not automatically confirm payment.</small></form></div><div class="col-lg-5"><div class="card border-0 shadow-sm p-4"><h2 class="h5">Order summary</h2><?php foreach($cart['items'] as $item):?><div class="d-flex justify-content-between gap-3 py-2 border-bottom"><span><?=e($item['name'])?> × <?= (int)$item['quantity']?></span><strong><?=money($item['line_total'])?></strong></div><?php endforeach;?><div class="d-flex justify-content-between mt-3"><span>Subtotal</span><strong><?=money($cart['subtotal'])?></strong></div><div class="d-flex justify-content-between mt-2"><span>Delivery</span><strong><?=money(setting('default_delivery_fee','0.00'))?></strong></div><hr><div class="d-flex justify-content-between fs-5"><strong>Total</strong><strong><?=money($cart['subtotal']+(float)setting('default_delivery_fee','0.00'))?></strong></div></div></div></div></section><?php require __DIR__.'/includes/footer.php';?>
